    """Fill the gaps between opposite-slope diagonals of the marker color."""
    h, w = len(grid), len(grid[0])
    marker = next((v for row in grid for v in row if v != 0), 0)
    out = [row[:] for row in grid]
    if marker == 0:
        return out

    # Diagonals c = r + a and c = b - r, respectively.
    rising = {c - r for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker}
    falling = {c + r for r, row in enumerate(grid) for c, v in enumerate(row) if v == marker}
    for a in rising:
        for b in falling:
            for r in range(h):
                left = max(0, min(w - 1, a + r))
                right = max(0, min(w - 1, b - r))
                lo, hi = sorted((left, right))
